x_(a){return"\uacc4\ud68d\ubcf4\ub2e4 "+a+"% \ub4a4\ucc98\uc838 \uc788\uc5b4\uc694. \ub2e4\uc74c \uc138\uc158\ubd80\ud130 \uc2e4\uc81c \ud398\uc774\uc2a4\uc5d0 \ub9de\ucdb0 \uc870\uc815\ub3fc\uc694."},
xa(a){return"\uc9c0\uae08 \uc18d\ub3c4\ub77c\uba74 "+a+"\uc5d0 \ubaa9\ud45c\uc5d0 \ub3c4\ub2ec\ud574\uc694. \uacc4\ud68d\ubcf4\ub2e4 \ube68\ub77c\uc694."},
xb(a){return"\uc9c0\uae08 \uc18d\ub3c4\ub77c\uba74 "+a+"\uc5d0 \ubaa9\ud45c\uc5d0 \ub3c4\ub2ec\ud574\uc694. \uacc4\ud68d\ubcf4\ub2e4 \ub2a6\uc5b4\uc694."},
gx9(){return"\ucd5c\uadfc \uba87 \uc8fc\uac04 \ud5a5\uc0c1\uc774 \uc5c6\uc5b4\uc694. \uac00\ubcbc\uc6b4 \ud55c \uc8fc\ub97c \ubcf4\ub0b4\uba74 \ub2e4\uc2dc \ub298\uc5b4\ub098\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544\uc694."},
