x8(a){return"\ud398\uc774\uc2a4\uac00 \uc804\ubcf4\ub2e4 "+a+"% \ub290\ub824\uc84c\uc5b4\uc694. \ud53c\ub85c\uac00 \uc313\uc600\uc744 \uc218 \uc788\uc5b4\uc694."},
xd(a){return"\ucd5c\uadfc 3\uac1c\uc6d4 \ub3d9\uc548 \uccb4\uc911\uc774 "+a+"kg \ubcc0\ud588\uc5b4\uc694."},
r_(a){return"\uacc4\ud68d\ud55c \ub0a0\uc744 "+a+"\uc77c \uc5f0\uc18d \uc644\ub8cc\ud588\uc5b4\uc694."},
gAO(){return"\ud50c\ub79c\uc740 \uc774\ub807\uac8c \uc791\ub3d9\ud574\uc694"},
gAN(){return"\ub0b4\uac00 \ud50c\ub79c\uc5d0 \ub9de\ucd94\ub294 \uac8c \uc544\ub2c8\ub77c \ud50c\ub79c\uc774 \ub098\uc5d0\uac8c \ub9de\ucdb0\uc694."},
gAM(){return"\uc9c0\uae08 \uc2e4\ub825\uc5d0\uc11c \uc2dc\uc791\ud574\uc694"},
gAL(){return"\uc624\ub298 \uc5bc\ub9c8\ub098 \ud560 \uc218 \uc788\ub294\uc9c0 \ubb3c\uc5b4\ubd10\uc694. \ud50c\ub79c\uc740 \uc77c\ubc18\uc801\uc778 \uc22b\uc790\uac00 \uc544\ub2c8\ub77c \uac70\uae30\uc11c \uc2dc\uc791\ud574\uc694."},
gAK(){return"\ub2e4\uce58\uc9c0 \uc54a\uace0 \ub298\ub824\uc694"},
gAJ(){return"\ubd80\ud558\ub294 \ud55c \uc8fc\uc5d0 \ucd5c\ub300 15%\uae4c\uc9c0\ub9cc \ub298\uace0, 4\uc8fc\ub9c8\ub2e4 \ud55c \uc8fc\ub294 \uac00\ubccd\uac8c \ud574\uc11c \ud68c\ubcf5\ud574\uc694."},
gAE(){return"\ub9e4\uc77c \ub9de\ucdb0\uc11c \uc870\uc815\ub3fc\uc694"},
gAD(){return"\uc6b4\ub3d9 \uc804\uc5d0 \ucee8\ub514\uc158\uc744 \uc54c\ub824 \uc8fc\uc138\uc694. \uadf8\uac83\uacfc \ud53c\ub85c, \uacb0\uacfc\ub97c \ubc14\ud0d5\uc73c\ub85c \uc624\ub298 \uc138\uc158\uc744 \uc870\uc815\ud558\uace0 \uc774\uc720\ub3c4 \uc54c\ub824 \ub4dc\ub824\uc694."},
