gAB(){return"\uc2e4\uc81c \ud398\uc774\uc2a4\uac00 \ud50c\ub79c\uc5d0\uc11c \ubc97\uc5b4\ub098\uba74 \uc0c8 \ub0a0\uc9dc\ub97c \uc81c\uc548\ud574\uc694. \ubb3b\uc9c0 \uc54a\uace0 \ubaa9\ud45c\ub97c \ubc14\uafb8\ub294 \uc77c\uc740 \uc5c6\uc5b4\uc694."},
gAI(){return"\ub370\uc774\ud130\ub294 \ud734\ub300\ud3f0 \ubc16\uc73c\ub85c \ub098\uac00\uc9c0 \uc54a\uc544\uc694"},
gAH(){return"\ubaa8\ub4e0 \uacc4\uc0b0\uacfc \uc800\uc7a5\uc740 \uae30\uae30 \uc548\uc5d0\uc11c \uc774\ub904\uc838\uc694. \uacc4\uc815\ub3c4 \ud074\ub77c\uc6b0\ub4dc\ub3c4 \uc5c6\uc5b4\uc694."},
grS(){return"\uc54c\uaca0\uc5b4\uc694"},
gzK(){return"\uc790\uc138\ud788 \uc54c\uc544\ubcf4\uae30"},
gph(){return"\ud50c\ub79c \uc791\ub3d9 \ubc29\uc2dd"},
gpg(){return"\ub4a4\ub85c"},
gzA(){return"Road To\ub294 \uc7a5\uae30 \ud50c\ub79c\uacfc \ub9e4\uc77c\uc758 \uc870\uc815\uc744 \uacb0\ud569\ud574\uc694. \ud50c\ub79c\uc740 \ubaa9\ud45c\uae4c\uc9c0\uc758 \uae38\uc744 \uc815\ud558\uace0, \ub9e4\uc77c\uc758 \uc870\uc815\uc740 \uac01 \uc138\uc158\uc744 \uadf8\ub0a0 \uc0c1\ud0dc\uc5d0 \ub9de\ucdb0\uc694. \ubaa8\ub4e0 \uacc4\uc0b0\uc740 \ud734\ub300\ud3f0\uc5d0\uc11c \uc774\ub904\uc838\uc694."},
